const escape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const manifestElement=document.querySelector('#manifest'),table=document.querySelector('#evals'),status=document.querySelector('#status'),runButton=document.querySelector('#run');
let manifest,report=null,localRunner=false,busy=false;
const pretty=x=>escape(JSON.stringify(x,null,2));
function score(r,key){const m=r?.scores?.[key];return m?`${Number(m.score).toFixed(2)}<details><summary>Judgment</summary><div class="reason">${escape(m.reason)}</div></details>`:'—';}
function render(){table.innerHTML=manifest.cases.flatMap(c=>['baseline','grounded'].map(variant=>{const r=report?.results.find(x=>x.case_id===c.id&&x.variant===variant);return `<tr><td>${escape(c.name)}<small>${escape(c.id)}</small><details><summary>Input & source</summary><pre>${pretty(c.inputs)}</pre><a href="${escape(c.source.url)}" target="_blank" rel="noopener">Source video</a></details></td><td>${variant}</td><td>${escape(c.reference.constraint)}<details><summary>Reference</summary><pre>${pretty(c.reference)}</pre></details></td><td>${r?`${escape(r.brief.constraint)}<details><summary>Full output</summary><pre>${pretty(r.brief)}</pre></details>`:'Not run'}</td>${['diagnosis_agreement','grounded_advice','missing_information','label_match'].map(k=>`<td>${score(r,k)}</td>`).join('')}<td>${r?Number(r.latency_seconds).toFixed(2)+'s':'—'}</td></tr>`;})).join('');status.textContent=busy?'Running evaluations…':report?`Run ${report.run_id} · ${report.model} · Scores 0–1`:'No completed model run. OpenAI returned no credits remaining.';runButton.disabled=busy;runButton.textContent=busy?'Running…':'Run evals';}
async function loadReport(){const response=await fetch('report.json?v='+Date.now());if(!response.ok)return;const value=await response.json();if(!Array.isArray(value.results)||value.results.some(r=>!manifest.cases.some(c=>c.id===r.case_id)||!['baseline','grounded'].includes(r.variant)))throw new Error('Report does not match the manifest.');report=value;}
async function run(){if(busy)return;busy=true;render();try{const response=await fetch('/api/evaluate',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!response.ok)throw new Error((await response.json()).error||'Could not start evaluation');while(true){await new Promise(resolve=>setTimeout(resolve,1800));const response=await fetch('/api/status');if(!response.ok)throw new Error('Lost connection to local runner');const job=await response.json();if(job.status==='failed')throw new Error(job.error);if(job.status==='completed')break;}await loadReport();busy=false;render();}catch(e){busy=false;render();status.textContent=e.message;}}
try{const response=await fetch('manifest.json');if(!response.ok)throw new Error('Could not load manifest.json');manifest=await response.json();manifestElement.value=JSON.stringify(manifest,null,2);await loadReport();if(['localhost','127.0.0.1'].includes(location.hostname)){try{const response=await fetch('/api/health');if(response.ok)localRunner=(await response.json()).runner===true;}catch{}}runButton.hidden=!localRunner;runButton.onclick=run;render();}catch(e){status.textContent=e.message;}
